import Foundation

// ─────────────────────────────────────────────────────────────────────────────
// WordPieceTokenizer (Plan M2-10-02 KD-3; D-M2-10-CONTEXT-8) — the BERT
// WordPiece pipeline, self-implemented (ZERO SPM dependencies; the vocab
// rides the model asset package).
//
// PIPELINE (the reference `transformers` BasicTokenizer + WordPiece,
// do_lower_case=True — the Chinese-BERT convention, pinned by the golden
// fixture `Tests/Fixtures/tokenizer_golden.json` generated by
// Scripts/ai-models/tokenizer_ref.py):
//
//   1. clean text (drop \0 / U+FFFD / control chars, normalize whitespace)
//   2. pad the BERT CJK code-point ranges with spaces (per-character split)
//   3. whitespace tokenize
//   4. per token: lowercase, strip accents (NFD, drop Mn), split on
//      punctuation (ASCII ranges + Unicode P* categories)
//   5. WordPiece greedy longest-match per word ("##" continuation prefix,
//      >100-char words → [UNK])
//   6. wrap [CLS] … [SEP], pad/truncate to the STATIC 52 shape (the
//      M2-10-01 export contract) with the attention mask alongside
//
// PURE FUNCTION: no bundle access, no side effects — the vocabulary is
// injected as text (`vocab.txt` content, one token per line, line number =
// id) or as a ready dictionary (the fixture-test face). Missing special
// tokens are a TYPED construction failure.
// ─────────────────────────────────────────────────────────────────────────────

public struct WordPieceTokenizer: Sendable {

    public enum TokenizerError: Error, Equatable, Sendable {
        /// The vocabulary text carried no tokens.
        case vocabularyEmpty
        /// One of the required special tokens is absent (the payload names
        /// the missing set).
        case missingSpecialTokens([String])
    }

    /// One encode result: the static-shape id/mask rows (both `maxTokens`
    /// long — the converted CLIP text tower consumes the static shape).
    public struct Encoded: Sendable, Equatable {
        public let tokenIDs: [Int64]
        public let attentionMask: [Int64]
        /// The padded token spelling (debug/golden face; `[PAD]`-trailed).
        public let tokens: [String]
    }

    /// Words longer than this become `[UNK]` whole (the reference default).
    public static let maxInputCharsPerWord = 100

    public let vocabulary: [String: Int]
    private let padID: Int64
    private let unkID: Int64
    private let clsID: Int64
    private let sepID: Int64

    /// The dictionary face (the golden-fixture test builds a reduced vocab
    /// from the fixture's own token inventory — the CI face has no model).
    public init(vocabulary: [String: Int]) throws {
        guard !vocabulary.isEmpty else { throw TokenizerError.vocabularyEmpty }
        let required = ["[PAD]", "[UNK]", "[CLS]", "[SEP]"]
        let missing = required.filter { vocabulary[$0] == nil }
        guard missing.isEmpty else {
            throw TokenizerError.missingSpecialTokens(missing.sorted())
        }
        self.vocabulary = vocabulary
        self.padID = Int64(vocabulary["[PAD]"]!)
        self.unkID = Int64(vocabulary["[UNK]"]!)
        self.clsID = Int64(vocabulary["[CLS]"]!)
        self.sepID = Int64(vocabulary["[SEP]"]!)
    }

    /// The `vocab.txt` face: one token per line, line number = token id
    /// (the shipped asset's exact spelling). A trailing newline is fine.
    public init(vocabText: String) throws {
        var vocab: [String: Int] = [:]
        var index = 0
        for line in vocabText.split(separator: "\n", omittingEmptySubsequences: false) {
            let token = String(line)
            if !token.isEmpty, vocab[token] == nil { vocab[token] = index }
            index += 1
        }
        try self.init(vocabulary: vocab)
    }

    // MARK: - Encode

    /// Full pipeline → the static-shape rows. `maxTokens` = the export
    /// contract's 52; overflow drops the TAIL pieces (the reference
    /// longest_first truncation keeps the head).
    public func encode(_ text: String, maxTokens: Int = 52) -> Encoded {
        precondition(maxTokens >= 2, "the [CLS]…[SEP] wrap needs two slots")
        var pieces: [String] = []
        pieces.reserveCapacity(maxTokens)
        for word in basicTokens(text) {
            pieces.append(contentsOf: wordPieces(for: word))
        }
        if pieces.count > maxTokens - 2 {
            pieces = Array(pieces.prefix(maxTokens - 2))
        }
        var tokens = ["[CLS]"]
        tokens.append(contentsOf: pieces)
        tokens.append("[SEP]")
        while tokens.count < maxTokens { tokens.append("[PAD]") }
        let ids = tokens.map { Int64(vocabulary[$0] ?? Int(unkID)) }
        let mask = tokens.map { $0 == "[PAD]" ? Int64(0) : Int64(1) }
        return Encoded(tokenIDs: ids, attentionMask: mask, tokens: tokens)
    }

    // MARK: - BasicTokenizer (steps 1-4)

    /// The cleaned/split word face (the WordPiece input; public for the
    /// golden tests' segmentation assertions).
    public func basicTokens(_ text: String) -> [String] {
        var cleaned = ""
        cleaned.reserveCapacity(text.count)
        for character in text {
            if character == "\u{0}" || character == "\u{FFFD}" { continue }
            if Self.isControl(character) { continue }
            cleaned.append(Self.isWhitespace(character) ? " " : character)
        }
        // CJK per-character padding (the BERT code-point ranges).
        var padded = ""
        padded.reserveCapacity(cleaned.count * 2)
        for character in cleaned {
            if Self.isChineseCharacter(character) {
                padded.append(" ")
                padded.append(character)
                padded.append(" ")
            } else {
                padded.append(character)
            }
        }
        var output: [String] = []
        for token in padded.split(separator: " ", omittingEmptySubsequences: true) {
            var word = String(token).lowercased()
            word = Self.stripAccents(word)
            output.append(contentsOf: Self.splitOnPunctuation(word))
        }
        return output.flatMap { $0.split(separator: " ").map(String.init) }
    }

    /// `_is_whitespace`: the four explicit ASCII whitespaces or Unicode Zs.
    private static func isWhitespace(_ character: Character) -> Bool {
        if character == " " || character == "\t" || character == "\n"
            || character == "\r" { return true }
        return character.unicodeScalars.allSatisfy {
            $0.properties.generalCategory == .spaceSeparator
        }
    }

    /// `_is_control`: Cc/Cf, EXCEPT the characters already counted as
    /// whitespace (the reference treats \t\n\r as whitespace, not control).
    private static func isControl(_ character: Character) -> Bool {
        if character == "\t" || character == "\n" || character == "\r" {
            return false
        }
        return character.unicodeScalars.allSatisfy {
            let category = $0.properties.generalCategory
            return category == .control || category == .format
        }
    }

    /// `_is_chinese_char`: the CJK ideograph/punctuation ranges the
    /// reference pads around (NOT the kana — katakana rides the regular
    /// WordPiece path, the golden fixture pins the difference).
    private static func isChineseCharacter(_ character: Character) -> Bool {
        guard let scalar = character.unicodeScalars.first,
              character.unicodeScalars.count == 1 else { return false }
        let value = scalar.value
        switch value {
        case 0x4E00...0x9FFF, 0x3400...0x4DBF, 0x20000...0x2A6DF,
             0x2A700...0x2B73F, 0x2B740...0x2B81F, 0x2B820...0x2CEAF,
             0xF900...0xFAFF, 0x2F800...0x2FA1F:
            return true
        default:
            return false
        }
    }

    /// `_run_strip_accents`: NFD, drop every Mn (non-spacing mark).
    private static func stripAccents(_ token: String) -> String {
        let decomposed = token.decomposedStringWithCanonicalMapping
        var stripped = ""
        stripped.reserveCapacity(decomposed.count)
        for scalar in decomposed.unicodeScalars
        where scalar.properties.generalCategory != .nonspacingMark {
            stripped.unicodeScalars.append(scalar)
        }
        return stripped
    }

    /// `_is_punctuation`: the ASCII punctuation ranges + every Unicode P*
    /// category (treats CJK punctuation as a split point, like the
    /// reference).
    private static func isPunctuation(_ character: Character) -> Bool {
        guard let scalar = character.unicodeScalars.first,
              character.unicodeScalars.count == 1 else { return false }
        let value = scalar.value
        if (33...47).contains(value) || (58...64).contains(value)
            || (91...96).contains(value) || (123...126).contains(value) {
            return true
        }
        return scalar.properties.generalCategory == .connectorPunctuation
            || scalar.properties.generalCategory == .dashPunctuation
            || scalar.properties.generalCategory == .openPunctuation
            || scalar.properties.generalCategory == .closePunctuation
            || scalar.properties.generalCategory == .initialPunctuation
            || scalar.properties.generalCategory == .finalPunctuation
            || scalar.properties.generalCategory == .otherPunctuation
    }

    private static func splitOnPunctuation(_ token: String) -> [String] {
        guard !token.isEmpty else { return [] }
        var output: [String] = []
        var current = ""
        for character in token {
            if isPunctuation(character) {
                if !current.isEmpty { output.append(current); current = "" }
                output.append(String(character))
            } else {
                current.append(character)
            }
        }
        if !current.isEmpty { output.append(current) }
        return output
    }

    // MARK: - WordPiece (step 5)

    /// Greedy longest-match; a word with ANY uncovered character degrades
    /// the WHOLE word to `[UNK]` (the reference semantics).
    func wordPieces(for word: String) -> [String] {
        let characters = Array(word)
        if characters.count > Self.maxInputCharsPerWord { return ["[UNK]"] }
        var output: [String] = []
        var start = 0
        while start < characters.count {
            var end = characters.count
            var match: String?
            while start < end {
                var piece = String(characters[start..<end])
                if start > 0 { piece = "##" + piece }
                if vocabulary[piece] != nil { match = piece; break }
                end -= 1
            }
            guard let match else { return ["[UNK]"] }
            output.append(match)
            start = end
        }
        return output
    }
}
